program:
"""The player cadence evolves. Each round it starts from the current champion.

It runs in its own process and is sent plain JSON each turn, so it sees only
what a player may see. Everything outside the markers stays put.
"""


# CADENCE:BEGIN
def choose(view: dict, moves: list[dict]) -> int:
    """Return one of `moves`. `view` is everything this player may see."""
    # Heuristic values for keeping tiles on the rack
    VAL = {
        "A": 1.0, "B": -2.0, "C": -0.5, "D": 0.5, "E": 2.5, "F": -1.5,
        "G": -0.5, "H": 1.0, "I": 0.5, "J": -2.5, "K": -1.5, "L": 1.0,
        "M": 1.0, "N": 1.5, "O": -0.5, "P": 0.5, "Q": -6.0, "R": 2.0,
        "S": 8.0, "T": 1.5, "U": -1.5, "V": -3.5, "W": -2.0, "X": 1.5,
        "Y": -0.5, "Z": -2.0, "?": 25.0,
    }

    # Scrabble letter values for endgame penalty/bonus calculations
    TILE_VALUES = {
        "A": 1, "B": 3, "C": 3, "D": 2, "E": 1, "F": 4, "G": 2, "H": 4,
        "I": 1, "J": 8, "K": 5, "L": 1, "M": 3, "N": 1, "O": 1, "P": 3,
        "Q": 10, "R": 1, "S": 1, "T": 1, "U": 1, "V": 4, "W": 4, "X": 8,
        "Y": 4, "Z": 10, "?": 0,
    }

    VOWELS = {"A", "E", "I", "O", "U"}

    bag = view.get("bag", 100)
    bag_size = len(bag) if hasattr(bag, "__len__") else bag
    leave_weight = max(0.0, min(1.0, bag_size / 7.0))

    grid = view.get("grid")
    TWS = {(0, 0), (0, 7), (0, 14), (7, 0), (7, 14), (14, 0), (14, 7), (14, 14)}
    open_tws_board = {pos for pos in TWS if not grid or grid[pos[0]][pos[1]] is None}

    # Unseen score for endgame
    unseen_score = 0
    if bag_size == 0:
        unseen = view.get("unseen", {})
        if hasattr(unseen, "items"):
            for char, count in unseen.items():
                unseen_score += TILE_VALUES.get(char.upper(), 0) * count
        else:
            for char in unseen:
                unseen_score += TILE_VALUES.get(char.upper(), 0)

    best_move = moves[0]
    best_utility = -float("inf")

    for move in moves:
        score = move["score"]
        leave = [c.upper() for c in move["leave"]] if move["leave"] else []

        # Endgame handling
        if bag_size == 0:
            if not leave:
                leave_val = 2.0 * unseen_score
            else:
                leave_val = -2.0 * sum(TILE_VALUES.get(c, 0) for c in leave)
            utility = score + leave_val
        else:
            leave_val = 0.0
            if leave:
                has_q = "Q" in leave
                has_u = "U" in leave
                for char in leave:
                    val = VAL.get(char, 0.0)
                    if char == "Q" and has_u:
                        val = 2.0
                    elif char == "U" and has_q:
                        val = 1.0
                    leave_val += val
                if has_q and not has_u:
                    leave_val -= 8.0
                # Duplicate penalty
                counts = {}
                for char in leave:
                    if char != "?":
                        counts[char] = counts.get(char, 0) + 1
                for char, count in counts.items():
                    if count > 1:
                        leave_val -= (count - 1) * (1.0 if char == "S" else 2.5)
                # Vowel/consonant balance
                vowels = sum(1 for c in leave if c in VOWELS)
                consonants = sum(1 for c in leave if c not in VOWELS and c != "?")
                total = vowels + consonants
                if total > 1:
                    ideal_v = round(total * 0.43)
                    leave_val -= abs(vowels - ideal_v) * 2.0
            utility = score + leave_val * leave_weight

        # Triple-word square penalty
        tws_penalty = 0.0
        if move["kind"] == "play" and move["tiles"] and grid:
            move_coords = {(t[0], t[1]) for t in move["tiles"]}
            tws_dists = {}
            for r, col, _, _ in move["tiles"]:
                if r in (0, 7, 14):
                    for tc in (0, 7, 14):
                        pos = (r, tc)
                        if pos in open_tws_board and pos not in move_coords:
                            dist = abs(col - tc)
                            if 1 <= dist <= 3:
                                step = 1 if tc > col else -1
                                blocked = any(grid[r][c_mid] is not None
                                              for c_mid in range(col + step, tc, step))
                                if not blocked:
                                    tws_dists[pos] = min(tws_dists.get(pos, 99), dist)
                if col in (0, 7, 14):
                    for tr in (0, 7, 14):
                        pos = (tr, col)
                        if pos in open_tws_board and pos not in move_coords:
                            dist = abs(r - tr)
                            if 1 <= dist <= 3:
                                step = 1 if tr > r else -1
                                blocked = any(grid[r_mid][col] is not None
                                              for r_mid in range(r + step, tr, step))
                                if not blocked:
                                    tws_dists[pos] = min(tws_dists.get(pos, 99), dist)
            for dist in tws_dists.values():
                tws_penalty += 10.0 if dist == 1 else (5.0 if dist == 2 else 3.0)

        utility -= tws_penalty

        # Tie‑breaker: prefer higher utility, then score, then play kind
        if (utility > best_utility or
            (utility == best_utility and (
                score > best_move["score"] or
                (score == best_move["score"] and move["kind"] == "play" and best_move["kind"] != "play")
            ))):
            best_utility = utility
            best_move = move

    return moves.index(best_move)
# CADENCE:END
